export function recommendMethods(query){const lower=query.toLowerCase();const tokens=[...(lower.match(/[a-z]+/g)||[]),...(lower.match(/[\u4e00-\u9fff]+/g)||[]).flatMap(s=>Array.from({length:Math.max(0,s.length-1)},(_,i)=>s.slice(i,i+2)))];return methods.map(item=>({item,score:[...new Set(tokens)].reduce((n,t)=>n+Number(`${item.title}${item.keywords}${item.method}`.includes(t)),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.item);}
export function searchImported(files,query){const q=query.trim().toLowerCase();if(!q)return [];return files.flatMap(file=>{const pos=file.content.toLowerCase().indexOf(q);return pos<0?[]:[{id:file.id,name:file.name,volume:file.volume,text:file.content.slice(Math.max(0,pos-90),pos+q.length+260)}];}).slice(0,8);}
